lemma Subgroup.dvd_relIndex_iff_of_prime {G : Type*} [Group G] {H K : Subgroup G}
    [(K.subgroupOf H).Normal] [K.IsFiniteRelIndex H] (p : ℕ) (hp : p.Prime) :
    p ∣ K.relIndex H ↔ ∃ x ∈ H, x ∉ K ∧ x ^ p ∈ K

theorem MeasurableEquiv.restrict_preimage {α β : Type*}
    {m0 : MeasurableSpace α} {m1 : MeasurableSpace β} (e : α ≃ᵐ β) (μ : Measure α) (s : Set β) :
    μ.restrict (e ⁻¹' s) = ((μ.map e).restrict s).map e.symm

lemma Set.injOn_image_iff {α β γ : Type*} {f : α → β} {g : β → γ} {s : Set α}
    (hf : s.InjOn f) :
    (f '' s).InjOn g ↔ s.InjOn (g ∘ f)

lemma Subgroup.IsFiniteRelIndex.of_isCompact {G : Type*} [Group G]
    [TopologicalSpace G] [SeparatelyContinuousMul G] {U K : Subgroup G}
    (hU : IsOpen (X := G) U) (hK : IsCompact (X := G) K) : U.IsFiniteRelIndex K

lemma IsIdempotentElem.ker_toCorner
    {R : Type*} [CommRing R] {e : R} (he : IsIdempotentElem e) :
    RingHom.ker (algebraMap R he.Corner) = Ideal.span {1 - e}

theorem exists_smul_quadraticTwist_eq_quadraticTwistBy {θ : L}
    (hθ : θ ∉ Set.range (algebraMap K L)) :
    ∃ C : VariableChange K, C • E.quadraticTwist L = E.quadraticTwistBy θ

theorem tsum_lambert_eq_evalInt (q : k) (hq : valuation k q < 1) (c : ℕ → ℤ) {F : ℤ⟦X⟧}
    (hF : ∀ n, PowerSeries.coeff n F = ∑ d ∈ n.divisors, c d) :
    ∑' m : ℕ, ((c (m + 1) : ℤ) : k) * q ^ (m + 1) / (1 - q ^ (m + 1)) = evalInt q F

theorem valuation_evalInt_le_pow (q : k) (hq : valuation k q < 1) {F : ℤ⟦X⟧}
    {M : ℕ} (hF : ∀ m < M, PowerSeries.coeff m F = 0) :
    valuation k (evalInt q F) ≤ valuation k q ^ M

@[simp] lemma equivOfEq_some {V V' : WeierstrassCurve F} (h : V = V') {x y : F}
    (hns : V.toAffine.Nonsingular x y) :
    equivOfEq h (some x y hns) = some x y (h ▸ hns)

theorem exists_variableChange_baseChange_eq_of_smul_eq {W₁ W₂ : WeierstrassCurve K}
    [IsIntegral R W₁] [IsIntegral R W₂] (D : VariableChange K) (hD : D • W₁ = W₂) (u₀ : Rˣ)
    (hau : algebraMap R K ↑u₀ = ↑D.u) : ∃ C₀ : VariableChange R, C₀.baseChange K = D

lemma map_smul_baseChange_eq (σ : L ≃ₐ[K] L) {V W : WeierstrassCurve K} {ρ : VariableChange L}
    (hρ : ρ • V.baseChange L = W.baseChange L) :
    (ρ.map σ.toAlgHom.toRingHom) • V.baseChange L = W.baseChange L

theorem Algebra.IsQuadraticExtension.exists_eq_algebraMap_add_algebraMap_mul {θ θ' : L}
    (hθ : θ ∉ Set.range (algebraMap K L)) (hθ' : θ' ∉ Set.range (algebraMap K L)) :
    ∃ a b : K, a ≠ 0 ∧ θ' = algebraMap K L b + algebraMap K L a * θ

theorem AdjoinRoot.eq_zero_of_mul_root_add_eq_zero {F : Type*} [Field F] {q : F[X]}
    [Fact (Irreducible q)] (hdeg : 2 ≤ q.natDegree) {a b : F}
    (hab : algebraMap F (AdjoinRoot q) a * root q
      + algebraMap F (AdjoinRoot q) b = 0) : a = 0 ∧ b = 0

theorem AdjoinRoot.root_notMem_range_algebraMap {F : Type*} [Field F] {q : F[X]}
    [Fact (Irreducible q)] (hdeg : 2 ≤ q.natDegree) :
    root q ∉ Set.range (algebraMap F (AdjoinRoot q))

theorem AdjoinRoot.isMaximal_map_maximalIdeal {A : Type*} [CommRing A] [IsLocalRing A] {P : A[X]}
    (hirr : Irreducible (P.map (residue A))) :
    ((maximalIdeal A).map (algebraMap A (AdjoinRoot P))).IsMaximal

theorem Polynomial.Monic.separable_map_algebraMap_of_separable_map_residue {P : R[X]}
    (hmonic : P.Monic) (hsep : (P.map (residue R)).Separable) :
    (P.map (algebraMap R K)).Separable

theorem IsLocalRing.maximalIdeal_le {R : Type*} [CommSemiring R] [IsLocalRing R] {J : Ideal R}
    (hJ : J ≠ ⊤) (h : IsLocalRing.maximalIdeal R ≤ J) :
    J.IsMaximal

theorem tensorProduct_ext {g h : L ⊗[K] M →ₗ[K] P}
    (H : ∀ (x : B) (y : M), g ((algebraMap _ L x) ⊗ₜ[K] y) = h ((algebraMap _ L x) ⊗ₜ[K] y))
    : g = h

theorem Algebra.IsQuadraticExtension.discrim_ne_zero {θ : L}
    (hθ : θ ∉ Set.range (algebraMap K L)) :
    Algebra.trace K L θ ^ 2 - 4 * Algebra.norm K θ ≠ 0

theorem Algebra.IsQuadraticExtension.norm_eq_neg_of_sq_eq {α : L} {d : K}
    (hαK : α ∉ Set.range (algebraMap K L)) (hα : α ^ 2 = algebraMap K L d) :
    Algebra.norm K α = -d

theorem Algebra.IsQuadraticExtension.trace_eq_zero_of_sq_eq {α : L} {d : K}
    (hαK : α ∉ Set.range (algebraMap K L)) (hα : α ^ 2 = algebraMap K L d) :
    Algebra.trace K L α = 0

theorem Submodule.mem_span_range_iff_exists {α M R : Type*}
    [Semiring R] [AddCommMonoid M] [Module R M] {v : α → M} {x : M} :
    x ∈ Submodule.span R (Set.range v) ↔ ∃ (s : Finset α) (c : α → R), ∑ i ∈ s, c i • v i = x

protected theorem mem_map_of_mem {R S : Type*}
    [NonUnitalNonAssocRing R] [NonUnitalNonAssocRing S]
    {F : Type*} [FunLike F R S] {f : F} {I : TwoSidedIdeal R}
    {x : R} (hx : x ∈ I) : f x ∈ I.map f

theorem ValuationSubring.isUnit_iff_valued_eq_one {K : Type*} [Field K] {Γ₀ : Type*}
    [LinearOrderedCommGroupWithZero Γ₀] [hv : Valued K Γ₀] (x : hv.v.valuationSubring) :
    IsUnit x ↔ Valued.v x.val = 1

theorem ValuationSubring.isUnit_of_valued_eq_one {K : Type*} [Field K] {Γ₀ : Type*}
    [LinearOrderedCommGroupWithZero Γ₀] [hv : Valued K Γ₀] (x : hv.v.valuationSubring)
    (hx : Valued.v x.val = 1) : IsUnit x

theorem ValuationSubring.valued_eq_one_of_isUnit {K : Type*} [Field K] {Γ₀ : Type*}
    [LinearOrderedCommGroupWithZero Γ₀] [hv : Valued K Γ₀] (x : hv.v.valuationSubring)
    (hx : IsUnit x) : Valued.v x.val = 1

